// Hand-written typed wrapper around the generated articles.json.
// articles.json is regenerated by scripts/buildDocsManifest.mjs; this file is stable.
import type { DocsFrontmatter } from "@yugioh-app/contracts";
import rawArticles from "./articles.json";

export interface ArticleData {
  meta: DocsFrontmatter;
  /** Article body rendered to HTML at build time. */
  html: string;
}

export const articles = rawArticles as Record<string, ArticleData>;
